// Generated by tools/import_s2b4_cards.pl: the title card's frame numbers, from its list of names (add a zone's name there and these move)
#ifndef _TITLECARDDATA_H
#define _TITLECARDDATA_H

enum {
    TC_NAMES = 17, // the frames of the names, 0 to TC_NAMES - 1
    TC_FRAME_ZONE = TC_NAMES, // the word ZONE
    TC_FRAME_ACT1 = TC_NAMES + 1, // the act numbers: three frames
    TC_FRAME_BANNER = TC_NAMES + 4, // SONIC THE HEDGEHOG
    TC_FRAME_EDGE = TC_NAMES + 5, // the zigzag edge
    TITLECARD_NAMES = TC_NAMES + 6, // the rows of the letters table: the frames that are no names have none
};

#endif
